item.text:
Бэкенд проверяет **HMAC-SHA256 с токеном бота**, партнёр — **Ed25519 публичным ключом Telegram**. Для Ed25519 установите `cryptography`: `pip install cryptography`.

Обе функции принимают исходную строку `Telegram.WebApp.initData` и возвращают проверенный объект `user`. При ошибке выбрасывается `InvalidInitData`.

```python
import base64
import hashlib
import hmac
import json
import re
import time
from urllib.parse import parse_qsl

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey


TELEGRAM_KEYS = {
    "production": bytes.fromhex(
        "e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d"
    ),
    "test": bytes.fromhex(
        "40055058a4ee38156a06562e52eece92a771bcd8346a8c4615cb7376eddf72ec"
    ),
}


class InvalidInitData(ValueError):
    pass


def _parse(raw: str) -> dict[str, str]:
    try:
        pairs = parse_qsl(
            raw,
            keep_blank_values=True,
            strict_parsing=True,
            encoding="utf-8",
            errors="strict",
            max_num_fields=100,
        )
    except ValueError as exc:
        raise InvalidInitData("Некорректная строка initData") from exc

    data = dict(pairs)
    if not data or len(data) != len(pairs) or "" in data:
        raise InvalidInitData("Пустые или повторяющиеся параметры")
    return data


def _check_string(data: dict[str, str], exclude: set[str]) -> bytes:
    # Значения уже URL-декодированы. JSON не пересобираем.
    return "\n".join(
        f"{key}={value}"
        for key, value in sorted(data.items())
        if key not in exclude
    ).encode("utf-8")


def _verified_user(data: dict[str, str], max_age: int) -> dict:
    # Вызывается только после криптографической проверки.
    try:
        auth_date = int(data["auth_date"])
    except (KeyError, ValueError) as exc:
        raise InvalidInitData("Отсутствует или некорректен auth_date") from exc

    now = int(time.time())
    if auth_date < now - max_age or auth_date > now + 30:
        raise InvalidInitData("initData просрочен или датирован будущим")

    try:
        user = json.loads(data["user"])
    except (KeyError, ValueError) as exc:
        raise InvalidInitData("Отсутствует или некорректен user") from exc

    if (
        not isinstance(user, dict)
        or type(user.get("id")) is not int
        or user["id"] <= 0
    ):
        raise InvalidInitData("Некорректный user.id")
    return user


# 1. Ваш бэкенд: токен хранится только на сервере.
def verify_backend(
    raw: str, bot_token: str, *, max_age: int = 300
) -> dict:
    data = _parse(raw)
    received_hash = data.get("hash", "")
    if not re.fullmatch(r"[0-9a-f]{64}", received_hash):
        raise InvalidInitData("Отсутствует или некорректен hash")

    secret = hmac.new(
        b"WebAppData", bot_token.encode("utf-8"), hashlib.sha256
    ).digest()

    # Исключаем только hash; signature, если есть, участвует.
    expected_hash = hmac.new(
        secret, _check_string(data, {"hash"}), hashlib.sha256
    ).hexdigest()

    if not hmac.compare_digest(expected_hash, received_hash):
        raise InvalidInitData("Неверный hash")

    return _verified_user(data, max_age)


# 2. Партнёр: нужны только initData и доверенный ID вашего бота.
def verify_partner(
    raw: str, bot_id: int, *, test: bool = False, max_age: int = 300
) -> dict:
    data = _parse(raw)
    message = (
        f"{bot_id}:WebAppData\n".encode("utf-8")
        + _check_string(data, {"hash", "signature"})
    )
    public_key = TELEGRAM_KEYS["test" if test else "production"]

    try:
        encoded = data["signature"]
        signature = base64.b64decode(
            encoded + "=" * (-len(encoded) % 4),
            altchars=b"-_",
            validate=True,
        )
        Ed25519PublicKey.from_public_bytes(public_key).verify(
            signature, message
        )
    except (KeyError, ValueError, InvalidSignature) as exc:
        raise InvalidInitData("Неверная или отсутствующая signature") from exc

    return _verified_user(data, max_age)


# Применение на соответствующих серверах:
# user = verify_backend(init_data, BOT_TOKEN)
# user = verify_partner(init_data, BOT_ID)
# telegram_user_id = user["id"]
```

Партнёр задаёт `bot_id` и окружение в своей конфигурации. Токен и производный HMAC-ключ остаются у вас. Используйте исходный `initData`, а не `initDataUnsafe`.

Лимит 300 секунд и допуск часов 30 секунд — выбранная политика сервиса. Проверка возраста ограничивает повторное использование, но не делает данные одноразовыми; после входа можно выдавать собственную сессию.

Официальные алгоритмы: [HMAC](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app) и [Ed25519 для партнёров](https://core.telegram.org/bots/webapps#validating-data-for-third-party-use).
